  console.log(`Reading page ${p}...`);
  const products = await getPageProducts();
  console.log(`Page ${p} has ${products.length} products`);
  allPagesProducts.push(...products);

  if (p < 6) {
    await browserjs(tabId, () => {
      const nextBtn = document.querySelector('[data-analytics-pagination="next"]');
      if (nextBtn) nextBtn.click();
    });
    await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });
  }
}

// Deduplicate across pages
const finalProducts = [];
const seenUrls = new Set();
for (const prod of allPagesProducts) {
  if (!seenUrls.has(prod.link)) {
    seenUrls.add(prod.link);
    finalProducts.push(prod);
  }
}

