const airDetails = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('a'))
    .filter(a => a.innerText && a.innerText.startsWith('Refurbished') && /iPad\s*Air/i.test(a.innerText))
    .map(a => {
