      return {
        title: a.innerText.trim(),
        href: a.href,
        rawText: text
      };
    });

  // Deduplicate by href
  const unique = [];
  const seen = new Set();
  for (const item of items) {
    if (!seen.has(item.href)) {
      seen.add(item.href);
      unique.push(item);
    }
  }

  return unique;
});

