      seen.add(l.href);
      uniqueProductLinks.push(l);
    }
  }

  return {
    totalProductLinks: productLinks.length,
    uniqueProductLinksCount: uniqueProductLinks.length,
    sample: uniqueProductLinks.slice(0, 10)
  };
});

