const tabId = 118779795;

// Let's write a function to collect products on the current page
async function getPageProducts() {
  return await browserjs(tabId, () => {
    // Find all product links
    const tiles = Array.from(document.querySelectorAll('.rc-producttile, li, div'))
      .map(el => {
        const titleEl = el.querySelector('h3, .rf-refurb-productcard-title, a[data-autom="productTitle"]');
        const linkEl = el.querySelector('a[href*="/shop/product/"]');
        const priceEl = el.querySelector('.rf-refurb-price-current, .as-price-currentprice, .now-price');
        if (titleEl && linkEl) {
          return {
            title: titleEl.innerText.trim(),
            link: linkEl.href,
            price: priceEl ? priceEl.innerText.trim() : el.innerText.match(/\$[\d,]+(\.\d{2})?/)?.[0] || null,
            fullText: el.innerText.trim().replace(/\s+/g, ' ')
          };
        }
        return null;
      })
      .filter(Boolean);

    // Deduplicate by link
    const unique = [];
    const seen = new Set();
    for (const t of tiles) {
      if (!seen.has(t.link)) {
        seen.add(t.link);
        unique.push(t);
      }
    }
    return unique;
  });
}

// Let's go to page 1 first
await browserjs(tabId, () => {
  const input = document.querySelector('[data-analytics-pagination="pageinput"]');
  if (input) {
    input.value = "1";
    input.dispatchEvent(new Event('change', { bubbles: true }));
    input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true }));
  }
});

await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

const allPagesProducts = [];

for (let p = 1; p <= 6; p++) {
  console.log(`Reading page ${p}...`);
  const products = await getPageProducts();
  console.log(`Page ${p} has ${products.length} products`);
  allPagesProducts.push(...products);

  if (p < 6) {
    await browserjs(tabId, () => {
      const nextBtn = document.querySelector('[data-analytics-pagination="next"]');
      if (nextBtn) nextBtn.click();
    });
    await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });
  }
}

// Deduplicate across pages
const finalProducts = [];
const seenUrls = new Set();
for (const prod of allPagesProducts) {
  if (!seenUrls.has(prod.link)) {
    seenUrls.add(prod.link);
    finalProducts.push(prod);
  }
}

console.log('Total unique products across all 6 pages:', finalProducts.length);

// Save to scratch file for inspection
await write("tmp://all_refurb_ipads.json", JSON.stringify(finalProducts, null, 2), "application/json");

