const todoPath = "tmp://sessions/channel%3Apanel%3Aada28ca7-557c-40f4-9e29-38113eb696ff/TODO.md";

const fileContent = await read("tmp://all_refurb_ipads.json");
const products = JSON.parse(fileContent.text);

// Filter for iPad Air
const ipadAirs = products.filter(p => /iPad\s*Air/i.test(p.title));
console.log(`Found ${ipadAirs.length} iPad Air products.`);

// Filter for 256GB
const airs256 = ipadAirs.filter(p => /256\s*GB/i.test(p.title));
console.log(`Found ${airs256.length} iPad Air 256GB products.`);

// Filter for blue shades (blue, sky blue, navy, cyan, teal, etc.)
// Check all unique colors in airs256 first
const colorRegex = /-\s*([A-Za-z\s]+)$/;
const colors = airs256.map(p => {
  const match = p.title.match(colorRegex);
  return match ? match[1].trim() : 'Unknown';
});
console.log('Colors available in 256GB iPad Air:', Array.from(new Set(colors)));

const blueAirs256 = airs256.filter(p => /blue/i.test(p.title));
console.log(`Found ${blueAirs256.length} Blue/Sky Blue iPad Air 256GB products:`);

// Parse prices
function parsePrice(str) {
  if (!str) return Infinity;
  const match = str.match(/\$([0-9,]+(\.[0-9]{2})?)/);
  if (!match) return Infinity;
  return parseFloat(match[1].replace(/,/g, ''));
}

const evaluated = blueAirs256.map(p => ({
  title: p.title,
  priceText: p.price,
  priceNumeric: parsePrice(p.price) || parsePrice(p.fullText),
  link: p.link
})).sort((a, b) => a.priceNumeric - b.priceNumeric);

console.log('Evaluated sorted by price:', JSON.stringify(evaluated, null, 2));

